import{_ as e,c as t,o as r,a0 as i}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Guide rapide du jeu mental","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/fr/summary-sheet.md","filePath":"public/downloads/fr/summary-sheet.md"}');const n=e({name:"public/downloads/fr/summary-sheet.md"},[["render",function(e,a,n,s,o,l){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="guide-rapide-du-jeu-mental" tabindex="-1">Guide rapide du jeu mental <a class="header-anchor" href="#guide-rapide-du-jeu-mental" aria-label="Permalink to &quot;Guide rapide du jeu mental&quot;">​</a></h1><p><strong>Académie de Pétanque - Résumé d&#39;une page</strong></p><hr><h2 id="l-39-etat-de-la-zone-du-flux" tabindex="-1">L&#39;état de la zone/du flux <a class="header-anchor" href="#l-39-etat-de-la-zone-du-flux" aria-label="Permalink to &quot;L&amp;#39;état de la zone/du flux&quot;">​</a></h2><p><strong>Deux modes d&#39;esprit :</strong></p><table tabindex="0"><thead><tr><th>Mode planification</th><th>Mode exécution</th></tr></thead><tbody><tr><td>Analysez le terrain</td><td>Écoutez votre corps</td></tr><tr><td>Choisissez une stratégie</td><td>Ne réfléchissez pas</td></tr><tr><td>Évaluer les risques</td><td>Moment présent</td></tr><tr><td>Prendre des décisions</td><td>Exécution automatique</td></tr></tbody></table><p><strong>Le changement :</strong> Planifiez à l&#39;avance, laissez faire pendant</p><hr><h2 id="critique-interieure-vs-coach-interieur" tabindex="-1">Critique intérieure vs coach intérieur <a class="header-anchor" href="#critique-interieure-vs-coach-interieur" aria-label="Permalink to &quot;Critique intérieure vs coach intérieur&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Critique intérieure ❌</th><th>Coach intérieur ✅</th></tr></thead><tbody><tr><td>« C&#39;était terrible ! »</td><td>« Que puis-je en tirer ? »</td></tr><tr><td>&quot;Tu fais toujours des bêtises&quot;</td><td>&quot;Prochaine chance, nouveau départ&quot;</td></tr><tr><td>&quot;Tout le monde te regarde échouer&quot;</td><td>&quot;Je l&#39;ai déjà fait&quot;</td></tr><tr><td>&quot;Tu n&#39;es pas assez bon&quot;</td><td>&quot;Fais confiance au processus&quot;</td></tr></tbody></table><p><strong>Recadrage :</strong> Pause → Recadrage → Réinitialisation → Recentrage</p><hr><h2 id="reinitialisation-en-3-respirations" tabindex="-1">Réinitialisation en 3 respirations <a class="header-anchor" href="#reinitialisation-en-3-respirations" aria-label="Permalink to &quot;Réinitialisation en 3 respirations&quot;">​</a></h2><p><strong>À utiliser après des erreurs ou une pression :</strong></p><ol><li><strong>Respiration 1 :</strong> Remarquez la tension (où ?)</li><li><strong>Respiration 2 :</strong> Relâchez la tension (lâchez prise)</li><li><strong>Respiration 3 :</strong> Recentrage (sur cette prise, maintenant)</li></ol><hr><h2 id="routine-avant-le-tir" tabindex="-1">Routine avant le tir <a class="header-anchor" href="#routine-avant-le-tir" aria-label="Permalink to &quot;Routine avant le tir&quot;">​</a></h2><p><strong>Même routine, à chaque prise :</strong></p><ol><li><strong>Visualiser</strong> - Voir la photo</li><li><strong>Respirez</strong> - Une grande inspiration</li><li><strong>Ancre</strong> - Touchez la boule, sentez le poids</li><li><strong>Exécuter</strong> - Faire confiance et jeter</li></ol><hr><h2 id="protocole-de-recuperation-des-erreurs" tabindex="-1">Protocole de récupération des erreurs <a class="header-anchor" href="#protocole-de-recuperation-des-erreurs" aria-label="Permalink to &quot;Protocole de récupération des erreurs&quot;">​</a></h2><p><strong>Après un mauvais tir :</strong></p><ol><li><strong>Reconnaître</strong> - « Cela ne s&#39;est pas passé comme prévu »</li><li><strong>Relâchement</strong> - Réinitialisation physique (secouez-le)</li><li><strong>Refocus</strong> - « La prochaine prise est nouvelle »</li><li><strong>Exécuter</strong> - Faites confiance à votre routine</li></ol><hr><h2 id="entrainement-de-cette-semaine" tabindex="-1">Entraînement de cette semaine <a class="header-anchor" href="#entrainement-de-cette-semaine" aria-label="Permalink to &quot;Entraînement de cette semaine&quot;">​</a></h2><p><strong>Choisissez UNE technique :</strong></p><ul><li>[ ] Réinitialisation en 3 respirations après chaque erreur</li><li>[ ] Routine de préparation avant chaque lancer</li><li>[ ] Recadrer une pensée de la critique intérieure par session</li><li>[ ] Pratiquez le passage du mode planification au mode exécution</li></ul><hr><h2 id="suivez-vos-progres" tabindex="-1">Suivez vos progrès <a class="header-anchor" href="#suivez-vos-progres" aria-label="Permalink to &quot;Suivez vos progrès&quot;">​</a></h2><p><strong>Avis:</strong></p><ul><li>À quel moment vous sentez-vous le plus en état de flow ?</li><li>Qu’est-ce qui déclenche votre critique intérieure ?</li><li>Quelle technique vous aide le plus ?</li><li>Comment vos performances évoluent-elles ?</li></ul><hr><h2 id="principes-cles" tabindex="-1">Principes clés <a class="header-anchor" href="#principes-cles" aria-label="Permalink to &quot;Principes clés&quot;">​</a></h2><ol><li><strong>Le flow est accessible</strong> - Vous pouvez apprendre à y entrer régulièrement.</li><li><strong>Votre voix intérieure compte</strong> - Encouragez-vous, ne vous critiquez pas.</li><li><strong>Des outils simples qui fonctionnent</strong> - 3 respirations, une routine, une réinitialisation</li><li><strong>La pratique est essentielle</strong> - Les compétences mentales nécessitent un entraînement, tout comme les compétences techniques.</li></ol><hr><h2 id="ressources" tabindex="-1">Ressources <a class="header-anchor" href="#ressources" aria-label="Permalink to &quot;Ressources&quot;">​</a></h2><p><strong>Poursuivez votre apprentissage sur carreau.app :</strong></p><ul><li>La Zone - Exploration approfondie de l&#39;état de flux</li><li>Force mentale - Gestion avancée du stress</li><li>Modèle d&#39;objectif - Structurez votre développement</li><li>Modèle de journal intime - Suivez vos progrès</li></ul><hr><p><strong>N&#39;oubliez pas :</strong> L&#39;entraînement mental ne se résume pas à la pensée positive. Il s&#39;agit de techniques pratiques qui vous aident à atteindre votre meilleur niveau de performance sous pression.</p><hr><p><em>Académie de Pétanque - Développement des joueurs élites</em><em>carreau.app</em></p>',42)])])}]]);export{a as __pageData,n as default};
